package org.apache.commons.math.optimization.general;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxEvaluationsExceededException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.exception.LocalizedFormats;
import org.apache.commons.math.linear.InvalidMatrixException;
import org.apache.commons.math.linear.LUDecompositionImpl;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.optimization.DifferentiableMultivariateVectorialOptimizer;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.SimpleVectorialValueChecker;
import org.apache.commons.math.optimization.VectorialConvergenceChecker;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math3.exception.NotImplementedException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for AbstractLeastSquaresOptimizer#getRMS.
 * Since the class is abstract and the fields are protected/private, 
 * we use a concrete subclass and reflection to inject test data.
 */
public class AbstractLeastSquaresOptimizer_getRMS_TriageGen3Test {

    private TestOptimizer optimizer;

    // Concrete implementation for testing abstract class
    private static class TestOptimizer extends AbstractLeastSquaresOptimizer {
        protected TestOptimizer() {
            super();
        }

        @Override
        protected org.apache.commons.math3.optim.PointValuePair doOptimize() {
            // Not needed for getRMS test
            throw new NotImplementedException();
        }
    }

    @Before
    public void setUp() {
        optimizer = new TestOptimizer();
    }

    /**
     * Helper method to set private/protected fields via reflection
     */
    private void setField(String fieldName, Object value) throws Exception {
        Field field = AbstractLeastSquaresOptimizer.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(optimizer, value);
    }

    @Test
    public void testGetRMS_StandardCalculation() throws Exception {
        // Setup data: residuals = [3.0, 4.0], weights = [1.0, 1.0], rows = 2
        // criterion = (3^2 * 1) + (4^2 * 1) = 9 + 16 = 25
        // expected = sqrt(25 / 2) = sqrt(12.5) ≈ 3.5355339059327378
        double[] residuals = {3.0, 4.0};
        double[] weights = {1.0, 1.0};
        int rows = 2;

        setField("residuals", residuals);
        setField("residualsWeights", weights);
        setField("rows", rows);

        double expected = Math.sqrt(25.0 / 2.0);
        Assert.assertEquals(expected, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_WithWeights() throws Exception {
        // Setup data: residuals = [2.0, 2.0], weights = [0.5, 2.0], rows = 2
        // criterion = (2^2 * 0.5) + (2^2 * 2.0) = (4 * 0.5) + (4 * 2.0) = 2 + 8 = 10
        // expected = sqrt(10 / 2) = sqrt(5) ≈ 2.23606797749979
        double[] residuals = {2.0, 2.0};
        double[] weights = {0.5, 2.0};
        int rows = 2;

        setField("residuals", residuals);
        setField("residualsWeights", weights);
        setField("rows", rows);

        double expected = Math.sqrt(5.0);
        Assert.assertEquals(expected, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_ZeroResiduals() throws Exception {
        double[] residuals = {0.0, 0.0, 0.0};
        double[] weights = {1.0, 1.0, 1.0};
        int rows = 3;

        setField("residuals", residuals);
        setField("residualsWeights", weights);
        setField("rows", rows);

        Assert.assertEquals(0.0, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_SingleElement() throws Exception {
        double[] residuals = {10.0};
        double[] weights = {1.0};
        int rows = 1;

        setField("residuals", residuals);
        setField("residualsWeights", weights);
        setField("rows", rows);

        // sqrt(10^2 * 1 / 1) = 10
        Assert.assertEquals(10.0, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_EmptyRows() throws Exception {
        // If rows is 0, the loop doesn't run, criterion remains 0.
        // Result is sqrt(0/0) which is NaN.
        double[] residuals = new double[0];
        double[] weights = new double[0];
        int rows = 0;

        setField("residuals", residuals);
        setField("residualsWeights", weights);
        setField("rows", rows);

        Assert.assertTrue(Double.isNaN(optimizer.getRMS()));
    }
}
